compile.workshop:
variables {
    global:
        0: total
        8: I
}

rule ("for loop") {
    event {
        Ongoing - Global;
    }
    actions {
        For Global Variable(I, 0, 10, 1);
            Modify Global Variable(total, Add, 1);
        End;
    }
}

